export const bookGrammar: Record<string, Record<string, GrammarNote[]>> = {"a-aki":{"simplified":[{"example":"たくさん書いてありました","tip":"Used with transitive verbs to focus on the result of someone's action rather than who did it.","meaning":"Indicates a state that remains as the result of a conscious action.","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"Use this for natural laws, machines (pushing buttons), or fixed sequences of events.","meaning":"When A occurs, B naturally or inevitably follows.","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"Indicates that the information was heard or read from another source (hearsay).","tip":"Unlike 'looks like' (sou desu), the hearsay version always follows the dictionary form (plain form).","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"Using 'ni omou' often suggests an emotional reaction or a subjective perspective.","meaning":"To feel or think a certain way instinctively.","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"While a certain state or condition continues.","tip":"Often implies that if you don't do it now, the chance will disappear (e.g., while it's still summer).","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form)","example":"夏休みに海へ行こう","tip":"With Group 2 verbs (ru-verbs), replace 'ru' with 'you'. With Group 1 (u-verbs), change the 'u' sound to 'o' and add 'u'.","meaning":"The 'let's' form, used to express intent or an invitation."},{"example":"話しているのを見ると","tip":"Use 'no' instead of 'koto' when the following verb involves direct perception like seeing, hearing, or waiting.","meaning":"Normalizing a verb to turn an action into a noun/object.","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"It suggests a logical guess based on evidence, similar to 'it seems that' or 'it looks as if'.","meaning":"Expresses a conjecture or appearance based on what the speaker has observed."}],"intermediate":[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"Focus on the preparation aspect; it means doing something now so you are ready for later.","meaning":"To do something in advance or for future use.","jlpt":"N4"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It often expresses a logical result.","meaning":"Conditional \"if\" or \"when\".","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"It seems that... / I heard that... (indicating an inference based on evidence).","tip":"Use this when you have some basis for your guess but aren't 100% certain.","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"It is used to describe the degree of a state or emotion by providing an example.","meaning":"To the extent that... / So much so that...","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"When/if (followed by a natural or inevitable consequence).","tip":"In this context, it marks the discovery of something that happens naturally when you take an action."},{"meaning":"Despite / Although / Even though (often used at the end of a sentence to show regret or frustration).","tip":"When it ends a sentence, it often implies \"I wish it weren't so\" or \"despite the situation.\"","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"When it comes to being... / If someone becomes a... (emphasizes a special status or rank).","tip":"This is used for high-level positions or significant situations where expectations naturally change."}],"original":[{"meaning":"to do something in advance for future use or to leave something in a certain state.","tip":"In speech, this often contracts: ～ておく becomes ～とく.","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"indicates a guess based on observation or information; 'it seems like' or 'apparently'.","jlpt":"N4","tip":"Unlike 'yoda', 'rashii' is used when you have some objective basis or rumors for your conclusion.","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"A literary or formal negative form of a verb, equivalent to ～ない.","tip":"You will see this often in literature or proverbs. 'Surnu' becomes 'senu' and 'kuru' becomes 'konu'.","jlpt":"N3"},{"meaning":"emphasizes that once a certain high level or special status is reached, things naturally change or become serious.","tip":"Used for roles, occupations, or special occasions to show a higher standard of expectation.","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"indicates the degree or extent of an action or state; 'to the extent that...'.","jlpt":"N3","tip":"Use this to add drama or emphasis to your descriptions by comparing them to an extreme limit."},{"meaning":"indicates an expectation or belief that something should be/have been a certain way, often followed by regret or surprise when it isn't.","jlpt":"N3","tip":"If followed by 'noni', it strongly implies that the reality is the opposite of the expectation.","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"A formal/literary way to express reason or cause; 'because' or 'due to'.","tip":"This is very stiff and formal. In modern conversation, you would use 'node' or 'kara'. Shortened to 'yue' in some expressions.","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]},"kumo-no-ito":{"simplified":[{"jlpt":"N5","meaning":"Indicates a continuing state or an ongoing action.","pattern":"～ている/ていた","example":"白い花がたくさん咲いていて、いいにおいがしていました。","tip":"When used with verbs like 'to bloom' (saku), it describes a state rather than an active process."},{"tip":"Always use the short past (ta-form) before 'koto ga aru'.","example":"一つだけいいことをしたことがあります。","meaning":"Used to talk about past experiences (have done something before).","jlpt":"N5","pattern":"V-た + ことがある"},{"pattern":"V-volitional + とする","meaning":"To try to do or attempt an action.","jlpt":"N4","example":"踏もうとしましたが、やめました。","tip":"Often used when the attempt fails or is interrupted, like 'was about to [verb] but...'"},{"example":"生きたいと思っているはずだ","tip":"Use this when you have a logical reason to believe something must be the case.","jlpt":"N4","meaning":"Used to express a strong expectation or belief that something is true.","pattern":"～はずだ"},{"pattern":"～かもしれない","meaning":"Expresses a possibility that something might happen (might, perhaps).","jlpt":"N4","example":"極楽へ行けるかもしれない！","tip":"It's more uncertain than 'deshō'. In speech, it is often shortened to 'kamo'."},{"example":"犍陀多を地獄から助けようと思いました。","tip":"The volitional form + 'to omou' expresses a decision made in the moment or a general intention.","jlpt":"N4","meaning":"Expresses the speaker's (or subject's) intention or plan.","pattern":"V-volitional + と思う"},{"example":"とても悲しそうなかおをしました。","tip":"Drop the final 'i' or 'na' from the adjective before adding 'sō'. It means 'looks like' or 'seems'.","meaning":"Indicates that something looks a certain way based on appearance.","jlpt":"N4","pattern":"Adjective (stem) + そうな / そうに"},{"pattern":"V-volitional + と（する）","jlpt":"N3","meaning":"Describes an attempt to do something, often showing the subject's effort or struggle.","example":"自分だけ助かろうとしました。","tip":"In this context, it highlights Kandata's selfish attempt to save only himself."}],"intermediate":[{"tip":"When used with intransitive verbs like 'saku' (to bloom), it describes the current state of something.","example":"池に咲いている蓮の花は","pattern":"～ている","meaning":"Indicates an ongoing action (progressive) or a current state.","jlpt":"N5"},{"pattern":"～てやる","meaning":"To do something for someone (implied that the receiver is of lower status, a pet, or a plant).","jlpt":"N4","tip":"In polite speech, you should use 'ageru'. 'Yaru' is reserved for animals, plants, or subordinates.","example":"蜘蛛を助けてやったのです。"},{"pattern":"～かもしれない/～かもしれん","meaning":"Expresses a possibility that something might happen or be true (might, perhaps).","jlpt":"N4","tip":"It follows a plain form verb, noun, or adjective. It expresses a 50% or lower probability.","example":"地獄を抜け出せるかもしれない。"},{"jlpt":"N4","meaning":"Even if/even though. Used here as a repeated phrase to emphasize 'No matter how much I climb...'","pattern":"～ても / ～でも","example":"登っても登っても、極楽にはなかなか近づきません。","tip":"Repeating the 'verb-te mo' twice (e.g., tabe-te mo tabe-te mo) emphasizes persistence despite no change in the result."},{"example":"細い糸が切れてしまうかもしれない。","tip":"In this context, it shows the fear of an unfortunate, irreversible event (the thread snapping).","pattern":"～てしまう","jlpt":"N4","meaning":"Indicates completing an action entirely, or expressing regret/unintentionality."},{"pattern":"ご～になる (Honorific Verbs) / ご覧になる","jlpt":"N3","meaning":"The honorific form of 'miru' (to see/watch). Used to show high respect to the subject.","example":"その一部始終をご覧になっていました。","tip":"This is 'Sonkeigo'. Use it only for actions performed by someone you respect, never for yourself."},{"pattern":"～ようとする / ～ようとしている","jlpt":"N3","meaning":"To try to do or attempt to do something. Uses the volitional form.","example":"自分だけが助かろうとした犍陀多の心","tip":"It describes a point just before an action starts or an attempt to make something happen."},{"tip":"This emphasizes that an event happened so quickly that there wasn't even a moment for a secondary action.","example":"犍陀多は何かを言う間もなく、風を切って落ちていきました。","meaning":"Without even having the time to... or 'No sooner had... than...'","jlpt":"N2","pattern":"～（る）間もなく / ～暇もなく"}],"original":[{"meaning":"The polite form of the copula 'desu'. Frequently used in storytelling and formal narration.","tip":"In literature, it gives a graceful, old-fashioned, or high-status tone to the narrator.","pattern":"～でございます","jlpt":"N5","example":"ある日の事でございます。"},{"jlpt":"N4","example":"まっ白で、そのまん中にある金色の蕊からは...","meaning":"The Te-form of 'desu' (da), used to connect sentences or list qualities.","tip":"When used with nouns or Na-adjectives, it functions like 'and' to provide more information about the subject.","pattern":"～で (State-being)"},{"pattern":"～のが見える/聞こえる","tip":"Use 'no' instead of 'koto' when you are physically perceiving an action happening in real-time.","meaning":"Nominalizes a verb phrase to treat it as a noun, often used with verbs of perception like 'see' or 'hear'.","example":"蜘蛛が一匹、路ばたを這って行くのが見えました。","jlpt":"N4"},{"pattern":"～に違いない","meaning":"Expresses a strong certainty or conviction that something is true ( 'must be', 'without a doubt').","tip":"It is more subjective and based on the speaker's intuition compared to 'hazu da'.","jlpt":"N3","example":"命のあるものに違いない。"},{"example":"いくら焦って見た所で、容易に上へは出られません。","jlpt":"N2","tip":"Usually followed by a negative or pessimistic conclusion. 'Ikura' (no matter how much) is a common partner for this pattern.","meaning":"Used to say that 'even if' one does something, the result will not change or will be futile.","pattern":"～た所で (V-ta tokoro de)"},{"jlpt":"N2","example":"御釈迦様は極楽の蓮池のふちを...御歩きになっていらっしゃいました。","meaning":"The highest level of honorific speech (Sonkeigo). It uses the prefix 'o' + stem + 'ni naru' combined with 'irassharu'.","tip":"This marks the subject (Buddha) as much higher in status than the narrator or listener. 'Irassharu' is the honorific version of 'iru'.","pattern":"お～になる / いらっしゃる"},{"example":"この男を地獄から救い出してやろうと御考えになりました。","jlpt":"N4","meaning":"The volitional form + 'to omou' expresses the speaker's (or subject's) intention or plan.","tip":"Adding 'to suru' instead of 'to omou' stresses that the person is just about to start the action or is making an effort.","pattern":"～ようと思う / ～ようとする"}]},"rashomon":{"simplified":[{"tip":"Use 'no wa' for subjects and 'no o' for objects. It allows you to talk about actions as if they are things.","meaning":"Turns a verb or clause into a noun (nominalization).","example":"泥棒になるのは嫌だ","jlpt":"N5","pattern":"～のは / ～のが / ～のを"},{"tip":"Use the dictionary form for positive changes and the 'nai' form (e.g., konaku naru) for negative changes.","meaning":"Indicates a change that happens over time or reaching a certain state.","jlpt":"N4","example":"動物や泥棒が住むようになりました。","pattern":"V-dictionary form + ようになる"},{"tip":"Often translated as \"whenever\" or \"if.\" It's used for things that happen naturally, like seasonal changes or habitual actions.","pattern":"～と","example":"夕方になると、みんな怖がって門の近くに来なくなりました。","jlpt":"N4","meaning":"Natural consequence or an automatic result; 'whenever A happens, B follows.'"},{"tip":"In Japanese, the passive is often used to express a sense of being bothered or affected by someone else's action.","meaning":"Passive voice; indicates that something was done to the subject.","jlpt":"N4","example":"「もう来なくていい」と言われました。","pattern":"V-passive (～られる)"},{"tip":"Use this when you have a logical reason to believe something is true. Note that 'shika... nai' means 'only.'","pattern":"～はずだ","example":"死んだ人しかいないはずです。","jlpt":"N3","meaning":"Expectation or strong belief that something should be the case."},{"meaning":"Doing two actions at the same time.","jlpt":"N3","example":"おばあさんは震えながら言いました。","pattern":"V-stem + ながら","tip":"The second action (the verb after 'nagara') is the main focus of the sentence."},{"tip":"While 'te kuru' usually implies moving toward the speaker/present, 'te iku' implies moving away from the present toward the future.","pattern":"V-te + いく","jlpt":"N3","example":"どうやって生きていけばいいかわかりませんでした。","meaning":"Expresses a progression or change starting from now and continuing into the future."},{"tip":"Use this to show that a result occurs regardless of the condition. It's the 'even if' pattern.","pattern":"V-te + も","meaning":"Even if... (concessive conditional).","example":"俺がお前の服を盗んでも怒るなよ。","jlpt":"N2"}],"intermediate":[{"pattern":"～の（を/が）","jlpt":"N4","meaning":"Nominalizing a verb/sentence so it can function as an object.","example":"雨がやむのを待っていた。","tip":"Use 'no' instead of 'koto' when the main verb involves perception (to see/hear) or waiting."},{"jlpt":"N4","pattern":"～ようになる / ～なくなる","tip":"Connects to dictionary form for 'become' and negative form for 'stop happening'.","example":"夕方になると誰も近づかなくなった。","meaning":"Indicates a change in state or habit (to become...)."},{"pattern":"～そうだ (appearance)","jlpt":"N4","meaning":"Expressing that something looks or appears a certain way.","example":"雨宿りをする人がいそうだが。","tip":"For 'i-adjectives', drop the final 'i'. For 'ii' (good), it becomes 'yosasou'."},{"meaning":"Used for emphasis to mean 'even' or 'to the extent that'.","tip":"It implies an extreme or unexpected level that goes beyond the normal range.","example":"死体を捨てていく習慣までできた。","jlpt":"N3","pattern":"～まで"},{"meaning":"Asking for advice or expressing uncertainty about what to do.","tip":"Commonly used with question words like 'doushite' or 'doyatte' to show confusion.","example":"どうやって生きていけばいいのか分からず。","jlpt":"N4","pattern":"～ばいい（か）"},{"pattern":"～かもしれない","jlpt":"N4","example":"死人の髪を抜くのは悪いことかもしれない。","tip":"In casual speech, this is often shortened to just 'kamo'.","meaning":"Expressing a possibility or something that 'might' be true."},{"jlpt":"N3","pattern":"～（な）ければ","tip":"This is the negative conditional form. It is often used to explain a necessary action or consequence.","example":"そうしなければ飢え死にしていたからだ。","meaning":"If that were not the case (conditional negative)."},{"meaning":"A strong prohibition (Don't do...!).","example":"俺が身ぐるみ剥いでも恨むなよ。","tip":"This is very blunt and masculine. Be careful not to use it with superiors!","pattern":"Verb (Dictionary Form) + な","jlpt":"N4"}],"original":[{"meaning":"Used to turn a verb/sentence into a noun so it can be the object of a verb.","jlpt":"N5","example":"雨のふるのを眺めていた。","pattern":"Verb (Plain) + の","tip":"Unlike すること, の is often used for things you perceive with your senses, like seeing or hearing."},{"tip":"Use 見える for things that come into your line of sight naturally, and 見られる for having the opportunity to see something.","pattern":"～が見える","example":"鴉の糞が、点々と白くこびりついているのが見える。","jlpt":"N4","meaning":"Indicates that something is visible or can be seen (state), rather than the act of looking."},{"pattern":"～ている","tip":"In literature, this often sets the scene or describes the ongoing state of a character.","jlpt":"N4","meaning":"Expresses a continuous action or a current state.","example":"雨やみを待っていた。"},{"tip":"It is based on objective reasons or logical deduction. In this text, it's used with 'beki' (should) for extra emphasis on duty.","pattern":"～はずだ / ～はずである","example":"主人の家へ帰る可き筈である。","jlpt":"N3","meaning":"Expresses a strong expectation or something that is naturally supposed to be the case."},{"tip":"Determines a sense of urgency or a lack of resources (physical or temporal).","pattern":"～余裕／暇（いとま）はない","example":"手段を選んでいる遑はない。","meaning":"Indicates that there is no time, room, or margin to do something.","jlpt":"N3"},{"pattern":"～以上（は）","tip":"The second part of the sentence often contains a judgment, a duty, or a logical necessity.","meaning":"Now that; since; as long as. Expresses a strong resolve or an inevitable consequence based on a fact.","jlpt":"N2","example":"朱雀大路にある以上は、..."},{"example":"衰微の小さな余波にほかならない。","jlpt":"N2","meaning":"Nothing but; none other than. Used to emphasize a definitive reason or identity.","tip":"This is a formal expression used to assert that there is no other possible explanation.","pattern":"～にほかならない"},{"example":"考えをたどった揚句に、...","meaning":"After a long process of... (usually leading to a negative or complicated result).","jlpt":"N2","tip":"It implies that someone went through a lot of trouble or spent a long time doing something, often to reach a difficult conclusion.","pattern":"～あげく（に）"}]},"hashire-merosu":{"simplified":[{"pattern":"～て / ～で","jlpt":"N5","example":"毎日、笛を吹いて、羊と遊んで生活しています。","meaning":"Connecting verbs or adjectives in a sequence ('and') or expressing a state.","tip":"Use the 'te-form' to list actions in chronological order or to link related ideas together."},{"jlpt":"N4","example":"美味しい食べ物を買うために、町に来たのです。","pattern":"～ために","meaning":"Expressing a purpose or reason ('in order to' / 'for the sake of').","tip":"When used after a verb, the verb must be in the dictionary form. It indicates a clear goal."},{"pattern":"～つもりだ","example":"メロスは彼に会いに行くつもりでした。","jlpt":"N4","tip":"Use this for firm intentions. Notice in the story it becomes 'was planning to' using the past tense 'deshita'.","meaning":"Expressing one's intention or plan to do something."},{"example":"あの悪い王様を倒さなければならない。","jlpt":"N4","pattern":"～なければならない / なければなりません","meaning":"Expressing obligation or necessity ('must' / 'have to').","tip":"This is a formal way to say 'must'. In casual speech, people often say 'nakya' or 'nakucha'."},{"meaning":"Expressing that a state remains unchanged while another action occurs ('left as it is' / 'staying in the state of').","tip":"Often used with the 'Ta-form' (past tense) of verbs to show that the result of an action is still continuing.","example":"メロスは、怒ったまま王様のお城に入りました。","jlpt":"N3","pattern":"～まま"},{"example":"メロスは泣きながら神様にお願いしました。","jlpt":"N4","pattern":"～ながら","tip":"Attach this to the verb stem (Masu-stem). The action after 'nagara' is usually the main focus.","meaning":"Performing two actions simultaneously ('while' / 'at the same time')."},{"jlpt":"N4","example":"三日目にあの友だちを殺してやろう。","pattern":"～てやる / ～てやろう (Volitional)","tip":"Be careful; using 'te yaru' for people can sound rude or aggressive. In this context, it shows the King's evil intent.","meaning":"Doing something for someone 'downward' in social status (or in this case, malevolently/selfishly)."}],"intermediate":[{"pattern":"～てくる","tip":"Think of it as 'coming' toward the present time. In this text, it shows Melos has lived this way for a long time.","meaning":"Indicates an action or state that has continued from the past up until the present.","jlpt":"N4","example":"羊と遊んで暮らしてきた。"},{"example":"これからその友人を訪ねるつもりだ。","meaning":"Indicates intention or a plan to do something.","jlpt":"N4","tip":"Used for firm intentions. Melos is set on visiting his friend.","pattern":"～つもりだ"},{"example":"歩いているうちに、メロスは町の様子がおかしいことに気がついた。","jlpt":"N3","meaning":"While a certain state or action is continuing, a change or an unexpected event occurs.","tip":"Commonly translated as 'while' or 'during,' it often implies the change happened before the speaker realized it.","pattern":"～うちに / ～ているうちに"},{"pattern":"～なければならない","tip":"Formed by adding -nakereba (if not) to naru (become). It literally means 'it won't do if you don't...'","meaning":"Indicates obligation or necessity; 'must' or 'have to.'","jlpt":"N4","example":"絶対に倒さなければならない。"},{"jlpt":"N3","meaning":"As; in the capacity of. Used to indicate a role, capacity, or status.","example":"花婿として迎えることになっていた。","pattern":"～として","tip":"Very common in formal and written Japanese to define someone's role or a thing's function."},{"tip":"The 'yaru' part adds the nuance of doing a favor for someone of lower status (like a younger sibling).","pattern":"～（さ）せてやりたい / ～（さ）せたい","example":"妹に夫を持たせてやりたいのです。","jlpt":"N4","meaning":"A combination of the Causative form (make/let someone do) and verb-tai (want to). It expresses a desire to let/make someone do something."},{"example":"生かしておくわけにはいかない。","jlpt":"N2","meaning":"Cannot afford to; must not (used when there is a strong social, moral, or situational reason why something is impossible).","tip":"This is stronger than 'cannot' (dekinai); it means that even if it's physically possible, it is not acceptable to do it.","pattern":"～わけにはいかない"}],"original":[{"tip":"Think of it as the action \"coming\" toward you through time from the past.","example":"羊と遊んで暮して来た。","pattern":"～てくる (～てきた)","jlpt":"N4","meaning":"Indicates an action or state that has continued from the past up to the present."},{"pattern":"～はずだ","example":"賑やかであった筈だが","tip":"Use this when you are logically convinced that something is true, like \"it's supposed to be...\"","meaning":"Expresses a strong expectation or belief that something should be the case, based on reason or knowledge.","jlpt":"N4"},{"tip":"Use V-dictionary form + tsumori for positive intentions, and V-nai + tsumori for negative intentions.","example":"これから訪ねてみるつもりなのだ。","pattern":"～つもりだ","meaning":"Expresses an intention or plan to do something.","jlpt":"N4"},{"meaning":"While a certain state or action is continuing, a change occurs or something else happens.","jlpt":"N3","example":"歩いているうちにメロスは、まちの様子を怪しく思った。","pattern":"～うちに","tip":"Often translated as \"while\" or \"before (a change happens).\" It implies a limited window of time."},{"tip":"In this context, it shows purpose. When used with a noun, you need the particle 'no' (Noun + のために).","example":"自分の地位を守る為か。","pattern":"～ため(に)","jlpt":"N3","meaning":"Indicates a purpose, goal, or reason (for the sake of, in order to)."},{"meaning":"An archaic or literary version of 'must' (nakereba naranai). 'Nu' is the classical negation.","jlpt":"N2","tip":"In modern Japanese, 'nu' is replaced by 'nai,' but 'neba naranu' is still used in formal writing, speeches, or literature for dramatic effect.","pattern":"～ねばならぬ (～なければならない)","example":"除かなければならぬ。"},{"tip":"It replaces or follows particles like 'ga' or 'o' to highlight that even the most basic or unexpected thing is included.","example":"人の心をさえ疑って居られる。","pattern":"～さえ","meaning":"Used to emphasize that something is an extreme example, implying \"even\" or \"if only.\"","jlpt":"N2"}]},"lemon":{"simplified":[{"jlpt":"N4","meaning":"Indicates a natural consequence, habit, or discovering something after an action. 'If/When A happens, B follows.'","example":"お酒を毎日飲んでいると、体が重くてだるい時が来ます。","tip":"When used for habits or natural phenomena (like 'If you push this button...'), you cannot use an opinion or request in the second half.","pattern":"～と"},{"tip":"For 'ii' adjectives, drop 'i' and add 'sou'. For 'ii' (good), it becomes 'yosasou'.","example":"壊れそうな町です。泥棒がいそうな暗い道や...","pattern":"～そう（だ・な）","jlpt":"N4","meaning":"Indicates that something looks like it is about to happen (with verbs) or appears to have a certain quality (with adjectives)."},{"meaning":"Used to describe two actions performed by the same person at the same time. 'While doing...'","jlpt":"N4","example":"私は町を歩きながら、とても幸せでした。","tip":"The main action comes at the end of the sentence. Keep the verb in its 'masu-stem' form.","pattern":"～ながら"},{"meaning":"Used to express completion of an action, or more commonly, a sense of regret or accidental occurrence.","jlpt":"N4","pattern":"～てしまう","tip":"In casual speech, 'teshimau' often changes to 'chau' and 'deshimau' to 'jau'.","example":"あんなに暗くて嫌な気持ちが、たった一つのレモンで消えてしまったのです。"},{"pattern":"～ようだ / ～ように","tip":"Use 'no' before 'you' when connecting to a noun (e.g., Akuma no you na).","example":"周りのごちゃごちゃした色が、全部そのレモンの黄色に吸い込まれるようでした。","meaning":"Used to express a likeness, a metaphor, or something that appears to be the case based on observation. 'As if' or 'Like'.","jlpt":"N3"},{"example":"このままレモンを置いて、知らないふりをして店を出たら...","tip":"The part before 'furi' must be in plain form (dictionary, ta, or nai form).","pattern":"～ふりをする","meaning":"To behave as if something is true when it is not. 'Pretending to...'","jlpt":"N3"}],"intermediate":[{"jlpt":"N5","meaning":"Follows a noun to describe a similarity or appearance (like/as)","pattern":"Noun + のような + Noun","example":"二日酔いのようなだるい時期","tip":"Use 'のような' to link two nouns; use 'のように' when modifying a verb or adjective."},{"pattern":"Verb stem + 続ける (つづける)","meaning":"Indicates the continuation of an action (to keep doing/continue to)","jlpt":"N4","example":"どこを歩いているのか分からなくなるまで歩き続けた。","tip":"This can describe an ongoing habit or an action done for a long duration without stopping."},{"pattern":"Verb stem + かける / かかった","meaning":"Indicates that something is in the middle of a process or has started but not finished.","jlpt":"N4","example":"壊れかかった街だ。","tip":"Commonly used for things starting to happen (like dying or breaking) or actions interrupted (like eating)."},{"example":"立ち上がって帰りたくなってしまう。","tip":"In casual speech, '〜てしまう' often becomes '〜ちゃう'. In this text, it reflects an uncontrollable impulse.","pattern":"Verb -te form + しまう / しまった","jlpt":"N4","meaning":"Indicates an action that happens unintentionally, or expresses regret/completion."},{"tip":"Use this when you want to express a change in your desires or feelings that you 'started to feel'.","example":"急に立ち上がって帰りたくなってしまう。","jlpt":"N3","meaning":"To become or start to feel (used with emotive verbs/adjectives to show a change in state).","pattern":"Verb stem/Adjective + たくなる / くなる"},{"example":"まるで自分がとても健康になったような錯覚に陥った。","tip":"Pairing 'まるて' at the start of the clause prepares the listener for a comparison that isn't literally true.","jlpt":"N3","meaning":"Used to express a metaphor or irony (Just as if... / as though...)","pattern":"まるで + [Noun/Verb] + よう/みたい"},{"meaning":"Expresses surprise, disbelief, or strong emotion regarding a specific fact.","jlpt":"N2","pattern":"Sentence/Noun + なんて","example":"たった一つのレモンで、こんなにも幸せになれるなんて。","tip":"It is a more casual version of 'などと', often used at the end of a sentence to show deep exclamation."}],"original":[{"tip":"The main action comes after the 'nagara' clause. In this text, it describes the narrator's habit of thinking while walking.","meaning":"While doing an action (simultaneous actions)","pattern":"～ながら","example":"そんな路を歩きながら","jlpt":"N4"},{"jlpt":"N4","example":"土に帰ってしまう","pattern":"～てしまう","meaning":"To do something completely, or to do something regrettable/unintentional","tip":"Here it emphasizes the finality of returning to the earth; the total completion of decay."},{"tip":"Used here to paint a vivid, chaotic picture of a backstreet by listing various sights.","meaning":"Listing actions or states among others (implies etc.)","pattern":"～たり ～たりする","example":"どこか親しみのある、汚い洗濯物が干してあったりがらくたが転がしてあったり...","jlpt":"N4"},{"tip":"When used at the end of a sentence like this, it often expresses a strong desire or a 'hoping' sentiment.","meaning":"If it were (expressing a wish or hypothetical condition)","pattern":"～（だった）ら","example":"ここがいつの間にかその市になっているのだったら。","jlpt":"N3"},{"tip":"Commonly used in speech and descriptive writing to list similar items or places as examples.","meaning":"Examples like A and B (informal list)","pattern":"～とか ～とか","example":"京都から何百里も離れた仙台とか長崎とか...","jlpt":"N3"},{"example":"よくそれを口に入れては父母に叱られたものだが","jlpt":"N2","pattern":"～たものだ","tip":"This is the classic way to express nostalgia in Japanese. It feels more emotional than 'te ita'.","meaning":"To recall a past habit or common occurrence ('used to')"},{"meaning":"Causative form: to make or let someone do something","tip":"Used here to show an external force or feeling compelling the narrator to act against his will.","jlpt":"N2","example":"何かが私を居堪らずさせるのだ。","pattern":"～させる"}]},"hana":{"simplified":[{"example":"知らない人はいません","pattern":"～ない～はいない","jlpt":"N5","meaning":"Double negative (lit. \"there is no one who doesn't know\") used to emphasize that 'everyone' knows.","tip":"In Japanese, using two negatives often makes the statement stronger and more formal than a simple affirmative."},{"meaning":"Used to describe something by comparing it to something else (simile).","tip":"Use this when something resembles another thing in appearance or manner. Use 'no yō da' at the end of a sentence and 'no yō ni' before a verb or adjective.","pattern":"～のようだ / ～のように","example":"ソーセージのようです","jlpt":"N4"},{"jlpt":"N4","example":"鼻を短く見せる方法","pattern":"V-(さ)せる","tip":"In this context, 'miseru' (to show) is the causative of 'miru' (to see). It is used to describe an action that influences the appearance of something.","meaning":"The Causative form, used here to mean \"to make something look\" or \"to let something look.\""},{"tip":"This focuses on the person receiving the action. It implies gratitude or that the action was requested.","meaning":"To have someone do something for you; receiving a favor.","jlpt":"N4","pattern":"V-て もらう","example":"鼻を踏んでもらいます"},{"meaning":"The passive voice combined with 'te mo' (even if). Here it marks the subject's nose being affected by someone else's action.","tip":"The passive '踏まれる' (fumareru) is used here. In Japanese, the person whose body part is affected is usually the subject of the passive sentence.","pattern":"V-(ら)れる ＋ ～ても","example":"鼻を踏まれても、全然痛くありません","jlpt":"N3"},{"example":"やってみることにしました","pattern":"V-ことにする","jlpt":"N3","meaning":"Indicates a personal decision to carry out an action.","tip":"Contrast this with 'koto ni naru' (it has been decided by outside forces). 'Koto ni suru' emphasizes your own will."},{"meaning":"Used to provide an explanation, focus, or to emphasize a discovery/reason.","tip":"This 'no desu' pattern is very common in storytelling to add an explanatory tone to the facts being presented.","example":"鼻が元の長さに戻ったのです。","pattern":"～（ん）です / ～（の）だ","jlpt":"N3"},{"example":"笑うようになります","pattern":"V-る ＋ ようになる","jlpt":"N3","meaning":"Indicates a change in state or the start of a new habit/behavior.","tip":"Use this to describe a shift from one condition to another (e.g., from 'not laughing' to 'laughing')."}],"intermediate":[{"jlpt":"N5","pattern":"～がいる/いない","meaning":"Used to indicate existence or presence. Combining with a negative ('shiranai hito') creates a double negative: 'There is no one who doesn't know' (Everyone knows).","tip":"Use 'iru' for living things and 'aru' for inanimate objects. In this text, it emphasizes the monk's fame.","example":"知らない人はいない。"},{"example":"十五センチくらいあって","meaning":"Approximately or about. Used to show an estimated amount, time, or length.","tip":"'Gurai' sounds slightly more casual than 'kurai', but they are interchangeable in most contexts.","pattern":"～くらい / ぐらい","jlpt":"N5"},{"jlpt":"N4","example":"ソーセージのようなものが","tip":"Think of this as 'in the manner of' or 'having the appearance of'. It's essential for descriptive writing.","meaning":"Used to describe something by comparing it to something else (similitude). Like / as if.","pattern":"Noun + のような + Noun / Noun + のように + Verb/Adj"},{"jlpt":"N4","example":"鼻を気にしていると言われるのが恥ずかしい","pattern":"Verb (Passive Form) / ～れる・～られる","tip":"In Japanese, the passive is frequently used to express how someone's actions affect you emotionally (the 'suffering passive').","meaning":"Passive voice. Used when an action is performed upon the subject, often expressing annoyance or an objective fact."},{"example":"鼻をお粥の中に入れてしまったことがあり","tip":"In this story, it highlights the accidental and unfortunate nature of the monk's nose falling into the porridge.","meaning":"1. To do something completely. 2. To do something accidentally or with regret.","pattern":"Verb (Te-form) + しまう / しまった","jlpt":"N4"},{"jlpt":"N3","pattern":"少しも～ない / 全く～ない","tip":"This is a common 'pair' (so-o) expression. When you hear 'sukoshi mo', listen for the 'nai' at the end!","meaning":"(Not) at all / (Not) even a little. Used with a negative verb to emphasize complete negation.","example":"お坊さんになったことを少しも後悔していなかった。"},{"example":"鼻なんか気にしていないという態度をとって","pattern":"Noun + なんか / なんて","meaning":"Used to emphasize feelings of disdain, humility, or to dismiss something as unimportant. Similar to 'things like' or 'such a thing as'.","tip":"The monk uses 'nanka' to pretend his nose is a trivial matter, even though he is obsessed with it.","jlpt":"N3"},{"jlpt":"N2","example":"試そうとしなかった。","pattern":"Verb (Volitional) + と（は）しない","meaning":"To (not) try to do something, or to (not) make an effort to do something. Used with the volitional form.","tip":"Using the negative 'to shinai' indicates that the person has no intention of doing the action or shows a lack of effort."}],"original":[{"meaning":"Double negative used to emphasize that 'everyone' knows or does something.","jlpt":"N4","pattern":"～ない者はない / ～ない～はない","example":"池の尾で知らない者はない。","tip":"It functions as a strong 'Every' or 'Everyone' by saying 'There is no one who does not...'"},{"example":"鼻と云う語が出て来るのを何よりも惧れていた。","tip":"Commonly used for titles, names, or defining specific concepts. In literature, the kanji 云う is often used instead of 言う.","pattern":"～と云う (という)","jlpt":"N4","meaning":"Used to define or name something. 'The thing/word called...'"},{"jlpt":"N4","meaning":"Indicates that an action is done to the subject. In this context, it describes a story being 'spread' or 'rumored'.","example":"鼻を粥の中へ落した話は、当時京都まで喧伝された。","tip":"When the subject is an inanimate object or an event (like a story), the passive voice is often used to describe its state in society.","pattern":"～れる / ～られる（受身）"},{"jlpt":"N3","meaning":"Shows the speaker's conjecture or guess. '...probably / must be'.","tip":"Used when the speaker is making a guess based on evidence or common sense. Often used with 'why' (なぜ) or 'because' (から).","example":"あの鼻だから出家したのだろう。","pattern":"～だろう / ～でしょう"},{"jlpt":"N3","meaning":"Indicates that as one process progresses, another state changes in proportion. 'The more... the more...'.","pattern":"～ば～ほど","example":"苦心すればするほど、かえって長く見えるような気さえした。","tip":"The first verb is in the conditional 'ba' form, and the second is the dictionary form + hodo. It is used to show a direct correlation."},{"jlpt":"N2","meaning":"Used to express that the subject doesn't feel or think a certain way, even if others might expect them to.","pattern":"～とは思っていない / とは思わない","tip":"The 'wa' emphasizes the negation of that specific thought or feeling. It shows a clear internal stance.","example":"鼻に煩される事が少くなったと思っていない。"},{"jlpt":"N1","meaning":"An archaic/literary way to say 'As if' or 'Like'. equivalent to ~のようだ.","example":"有れども無きが如くである。","tip":"You will mostly see this in formal writing, literature, or set idiomatic phrases. In modern Japanese, use 'no you da'.","pattern":"～（が）如く (ごとく) / 如き (ごとき)"}]}};
